import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易要義卷二 * 下","description":"周易要義 - 周易要義卷二 * 下","frontmatter":{"title":"周易要義卷二 * 下","description":"周易要義 - 周易要義卷二 * 下"},"headers":[],"relativePath":"classics/yaoyi/006.md","filePath":"classics/yaoyi/006.md"}'),r={name:"classics/yaoyi/006.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易要義卷二-下" tabindex="-1">周易要義卷二 * 下 <a class="header-anchor" href="#周易要義卷二-下" aria-label="Permalink to “周易要義卷二 * 下”">​</a></h1><p>欽定四庫全書</p><p>宋魏了翁輯豫至觀</p><p>䷏</p><p>坤下震上 豫：利建侯行師。正義曰：謂之「豫」者，取逸豫之義，以和順而動，動不違眾，眾皆說豫，故謂之豫也。動而眾說，故可「利建侯」也。以順而動，不加無罪，故可以「行師」也。無四德者，以逸豫之事不可以常行。豫，餘慮反，悅豫也，備豫也。馬雲：豫，樂。震宮一世卦，</p><p>豫之時義大矣哉者，嘆美為豫之善，言於逸豫之時，其義大矣。此嘆卦也。凡言不盡意者，不可煩文具說，故嘆之以示情，使後生思其餘蘊，得意而忘言也。然嘆卦有三體：一直嘆時，如「大過之時大矣哉」之例是也；二嘆時並用，如「險之時用大矣哉」之例是也。三嘆時並義，「豫之時義大矣哉」之例是也。夫立卦之體，各象其時，時有屯夷，事非一揆，故爻來適時，有兇有吉。人之生世，亦復如斯，或逢治世，或遇亂時，出處存身，此道豈小？故曰「大矣哉」也。然時運雖多，大體不出四種者：一者治時，頤養之世是也。二者亂時，大過之世是也；三者離散之時，解緩之世是也。四者改易之時，革變之世是也。故舉此四卦之時為嘆，餘皆可知。言用者，謂適時之用也。雖知居時之難，此事不小，而未知以何而用之耳。故坎、睽、蹇之時，宜用「君子，小人勿用」。用險取濟，不可為常，斟酌得宜，是用時之大略。舉險難等三卦，餘從可知矣。又言「義」者，姤卦注云：「凡言義者，不盡於所見，中有意謂」者也。是其時皆有義也。略明佚樂之世，相隨相遇之日、隱遁羈旅之時，凡五卦，其義不小，則餘卦亦可知也。今所嘆者十二卦，足以發明大義，恢弘妙理者也。凡於彖之末嘆雲「大哉」者，凡一十二卦，若豫、旅、遁、姤凡四卦，皆雲「時義」。案：姤卦注云：「凡言義者，不盡於所見，中有意謂。」以此言之，則四卦，卦各未盡其理，其中更有餘意，不可盡申，故總雲「義」也。隨之一卦亦言義，但與四卦其文稍別。四卦皆雲時義，隨卦則隨時之義者，非但其中別有義意，又取隨逐其時，故變雲「隨時之義」。大矣哉。睽、蹇、坎，此三卦皆雲「時用」。案：睽卦注云：「睽離之時，非小人之所能用。」蹇卦亦云：「非小人之所能用。」此二卦言「大矣哉」者，則是大人能用，故云「大矣哉」。其中更無餘義，唯大人能用，故云「用」不雲「義」也。坎卦「時用」，則與睽、蹇稍別，注云「非用之常，用有時也」，謂坎險之事，時之須用，利益乃大，與睽、蹇「時」、「用」文同而義異也。解之「時」、革之「時」、頤之「時」，大過之「時」，此四卦直雲「時」，不雲「義」與「用」也。案解卦注難解之時，非治難時，故不言「用」；體盡於解之名，無有幽隱，故不曰「義」。以此注言之，直雲「時」者，尋卦之名，則其意具盡，中間更無餘義。</p><p>象曰：「雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。」正義曰：案諸卦之象，或雲「雲上於天」，或雲「風行天上」，以類言之。今此應雲「雷出地上」，乃雲「雷出地奮，豫」者，雷是陽氣之聲，奮是震動之狀，雷既出地震動萬物，被陽氣而生，各皆逸豫，故云「雷出地奮，豫」也。「先王以作樂崇德」者，雷是鼓動，故先王法此鼓動而作樂，崇盛德業，樂以發揚盛德故也。「殷薦之上帝」者，用此殷盛之樂，薦祭上帝也，象雷出地而向天也。「以配祖考」者，謂以祖考配上帝，用祖用考，若周夏正郊天，配靈威仰，以祖后稷配也。配祀明堂五方之帝，以考文王也，故云「以配祖考」也。奮，方問反。殷，於勤反，馬雲：「盛也。」說文雲：「作樂之盛稱殷。」</p><p>六二，介於石，不終日，貞吉。處豫之時，得位履中，安夫貞正，不苟求「豫」者也。順不苟從，豫不違中，是以上交不諂，下交不瀆。明禍福之所生，故不苟說；辨必然之理，故不改其操。介如「石」焉，「不終日」明矣。介，音界，纖介。古文作「砎」，鄭故八反，雲：謂磨砎也。馬作「扴」，雲：觸小石聲。荀說，音悅。正義：象曰「不終日，貞吉」，以中正者釋「貞吉」之義。所以見其惡事，即能離去，不待終日守正吉者，以此六二居中守正，順不苟從，豫不違中，故不須待其一日，終守「貞吉」也。</p><p>六三，盱豫，悔，遲有悔。居下體之極，處兩卦之際，履非其位，承「動豫」之主，若其睢盱而豫，悔亦生焉。遲而不從，豫之所疾，位非所據，而以從豫，進退離悔，宜其然矣。盱，香於反，睢盱也。向雲：「睢盱，小人喜悅之貌。」王肅雲：「盱，大也。」鄭雲：「誇也。」說文雲：「張目也。」字林火孤反，又火於反。子夏作「紆」。京作「汙」。姚作「旴」，雲：「日始出。」引詩「旴日始旦」。睢，香維反。說文雲：「仰日也。」字林火佳反。</p><p>九四，由豫，大有得。勿疑，朋盍簪。處豫之時，居動之始，獨體陽爻，眾陰所從，莫不由之，以得其「豫」，故曰「由豫，大有得」也。夫不信於物，物亦疑焉，故「勿疑」，則朋合疾也。盍，合也；簪，疾也。由豫，由，從也。鄭雲：用也。馬作「猶」，雲：「猶豫，疑也。」盍，胡獵反，合也。簪，徐側林反。子夏傳同，疾也。鄭雲：「速也。」埤蒼同，王肅又祖感反。古文作「貸」，京作「梣」，馬作「臧」，荀作「宗」，虞作「戠」。戠，叢合也。蜀才本依京義從鄭。若能不疑於物，以信待之，則眾陰群朋合聚而疾來也。正義。象曰「由豫，大有得，志大行」者，釋「由豫，大有得」之意。眾陰既由之而豫，大有所得，是志意大行也。</p><p>䷐</p><p>震下兌上 隨：元、亨、利、貞，無咎。正義曰：「元亨」者，於相隨之世，必大得亨通。若其不大亨通，則元以相隨，逆於時也。「利貞」者，相隨之體，須利在得正。隨而不正，則邪僻之道，必須「利貞」也。「無咎」者，有此四德乃無咎。以苟相從，涉於朋黨，故必須四德乃「無咎」也。凡卦有四德者，或其卦當時之義即有四德，如乾、坤、屯、臨、無妄，此五卦之時，即能四德備具。其隨卦以惡相隨，則不可也。有此四德乃無咎，無此四德則有咎也。與前五卦其義稍別。隨，從也。震宮歸魂卦。</p><p>六二，系小子，失丈夫。陰之為物，以處隨世，不能獨立，必有系也。居隨之時，體分柔弱，而以乘夫剛動，豈能秉志？違於所近，隨此失彼，弗能兼與。五處己上，初處己下，故曰「系小子，失丈夫」也。正義曰：「小子」謂初九也，「丈夫」謂九五也。初九處卑，故稱「小子」。五居尊位，故稱「丈夫」。六二既是陰柔，不能獨立，所處必近系屬初九，故云「系小子」。既屬初九，則不得往應於五，故云「失丈夫」也。象曰「系小子，弗兼與」者，釋「系小子」之意。既隨此初九，則失彼九五丈夫，是不能兩處兼有</p><p>六三，系丈夫，失小子。隨有求得，利居貞。陰之為物，以處隨世，不能獨立，必有系也。雖體下卦，二已據初，將何所附？故舍初系四，志在「丈夫」。四俱無應，亦欲於己隨之，則得其所求矣，故曰「隨有求得」也。應非其正，以繫於人，何可以妄？故「利居貞」也。初處己下，四處己上，故曰「系丈夫，失小子」也。象曰：「系丈夫」，志舍下也。下謂初也。</p><p>䷑</p><p>巽下艮上 蠱：元亨，利涉大川。先甲三日，後甲三日。正義曰：「蠱者，事也。有事營為，則大得亨通。有為之時，利在拯難，故利涉大川也。先甲三日，後甲三日者，甲者創制之令，既在有為之時，不可因仍舊令。今用創制之令，以治於人，人若犯者，未可即加刑罰。以民未習，故先此宣令之前三日，殷勤而語之。又於此宣令之後三日，更丁寧而語之。其人不從，乃加刑罰也。」其褚氏、何氏、周氏等並同鄭義，以為甲者，造作新令之日。甲前三日，取改過自新，故用辛也。甲後三日，取丁寧之義，故用丁也。今案：輔嗣注「甲曰創制之令」，不雲創制之日。又巽卦九五：「先庚三日，後庚三日。」輔嗣注：「申命令為之庚。」輔嗣又云：「甲、庚皆申命之謂。」則輔嗣不以甲為創制之日。而諸儒不顧輔嗣注旨，妄作異端，非也。蠱，音古，事也，惑也，亂也。左傳雲：「於文，皿蟲為蠱。」又云：「女惑男，風落山，謂之蠱。」徐又姬祖反，一音故，巽宮歸魂卦。先，息薦反，彖並注同。後，胡豆反。</p><p>彖曰：「蠱，剛至，天行也。」正義曰：「剛上而柔下，巽而止，蠱」者，此釋蠱卦之名，並明稱「蠱」之義也。以上剛能斷制，下柔能施令，巽順止靜，故可以有為也。褚氏雲：「蠱者，惑也。物既惑亂，終致損壞，當須有事也，有為治理也。故序卦雲：蠱者，事也。」謂物蠱必有事，非謂訓蠱為事，義當然也。「蠱，元亨，而天下治」者，釋「元亨」之義。以有為而得「元亨」，是天下治理也。「利涉大川，往有事也」者，釋「利涉大川」也。蠱者，有為之時，拔拯危難，往當有事，故「利涉大川」。此則假外象以喻危難也。「先甲三日，後甲三日，終則有始，天行」者，釋「先甲三日，後甲三日」之義也。民之犯令，告之已終，更復從始，告之殷勤不已，若天之行。四時既終，更復從春為始，象天之行，故云「天行也」。釋注「蠱者」至「四時也」。正義曰：「蠱者，有事待能之時」者，物既蠱壞，須有事營為，所作之事，非賢能不可，故經雲：「幹父之蠱，幹則能也。</p><p>甲者，創制之令」者，甲為十日之首，創造之令為在後諸令之首，故以創造之令謂之為甲。故漢時謂令之重者謂之「甲令」，則此義也。</p><p>創制不可責之以舊者，以人有犯令而致罪者，不可責之舊法，有犯則刑，故須先後三日，殷勤語之，使曉知新令，而後乃誅。誅謂兼通責讓之罪，非專謂誅殺也。說，音悅。創，初亮反。此俗字也，依字作創。</p><p>象曰：「山下」至「育德」。正義曰：必雲「山下有風」者，風能搖動，散佈潤澤。今「山下有風」，取君子能以恩澤下振於民，育養已德振民象山下有風育德象山在上也振舊之慎，反，濟也。師讀音真。振振，仁厚也。「育」，王肅作「毓」，古「育」字。</p><p>初六，幹父之蠱，有子，考無咎。厲，終吉。處事之首，始見任者也。以柔巽之質，幹父之事，能承先軌，堪其任者也，故曰「有子」也。任為事首，能堪其事，「考」乃「無咎」也，故曰「有子，考無咎」也。當事之首，是以危也。能堪其事，故「終吉」也。「有子，考無咎」絕句。周依馬、王肅以「考」絕句。正義：「象曰幹父之蠱，意承考」者，釋「幹父之蠱」義。凡堪幹父事，不可小大損益，一依父命，當量事制宜，以意承「考」而已。對文父沒稱「考」，若散而言之，生亦稱「考」。若康誥雲「大傷厥考心」，是父在稱「考」。此避幹父之文，故變雲「考」也。</p><p>初六，幹父之蠱，有子，考無咎。厲，終吉。處事之首，始見任者也。以柔巽之質，幹父之事，能承先軌，堪其任者也，故曰「有子」也。任為事首，能堪其事，「考」乃「無咎」也，故曰「有子，考無咎」也。當事之首，是以危也。能堪其事，故「終吉」也。「有子，考無咎」絕句。周依馬、王肅以「考」絕句。正義：「象曰幹父之蠱，意承考」者，釋「幹父之蠱」義。凡堪幹父事，不可小大損益，一依父命，當量事制宜，以意承「考」而已。對文父沒稱「考」，若散而言之，生亦稱「考」。若康誥雲「大傷厥考心」，是父在稱「考」。此避幹父之文，故變雲「考」也。</p><p>䷒</p><p>兌下坤上。 臨：元亨，利，貞。至於八月有兇。正義曰：案序卦雲：「臨，大也。」以陽之浸長，其德壯大，可以監臨於下，故曰「臨」也。剛既浸長，說而且順，又以剛居中，有應於外，大得亨通而利正也，故曰「元亨，利貞」也。「至於八月有兇」者，以物盛必衰，陰長陽退，臨為建醜之月，從建醜至於八月建申之時，三陰既盛，三陽方退，小人道長，君子道消，故八月有兇也。以盛不可終保，聖人作易以戒之也。臨，如字，序卦雲：「大也。」坤宮二世卦</p><p>彖曰：臨，剛至不久也。正義曰：「臨，剛浸而長，說而順」者，此釋臨義也。據諸卦之例，「說而順」之下，應以臨字結之。此無「臨」字者，以其剛中而應，亦是臨義，故不得於剛中之上而加「臨」也。剛中而應，大亨以正，天之道者，天道以剛居中，而下與地相應，使物大得亨通而利正，故乾卦「元亨利貞」。今此臨卦其義亦然，故云「天之道也」。</p><p>八月者，何氏雲：從建子陽生，至建未為八月。褚氏雲：自建寅至建酉為八月。今案：此注云：小人道長，君子道消，宜據否卦之時，故以臨卦建醜而至否卦建申為八月也。</p><p>䷓</p><p>坤下巽上 觀，盥而不薦，有孚顒若。王道之可觀者，莫盛乎宗廟。宗廟之可觀者，莫盛於盥也。至薦簡略，不足復觀，故觀盥而不觀薦也。孔子曰：「禘自既灌而往者，吾不欲觀之矣。」盡夫觀盛，則「下觀而化」矣。故觀至盥則「有孚顒若」也。觀，官喚反，示也。乾宮四世卦。盥音管。</p><p>聖人以神道設教，而天下服矣。統說：觀之為道，不以刑制使物，而以觀感化物者也。神則無形者也。不見天之使四時，而四時不忒；不見聖人使百姓，而百姓自服也。</p><p>初六，童觀，小人無咎，君子吝。處於觀時，而最遠朝美，體於陰柔，不能自進，無所鑑見，故曰童觀。趣順而已，無所能為，小人之道也，故曰「小人無咎」。君子處大觀之時，而為童觀，不亦鄙乎！童觀，馬雲：「童猶獨也。」鄭雲：「稚也。」遠，袁萬反。朝，直遙反。</p><p>「童觀、𬮭觀」，皆讀為去聲也。觀國如字；或音官喚反。盡夫觀盛，故觀至大觀在上，王肅音官。以觀天下，徐唯此一字作官音。觀。盥而不薦，觀之為道，而以觀感。風行地上，觀。處於觀時。君子處大觀之時，大觀廣鑑亦音官。居觀之時，為觀之主，觀之盛也。從「盡夫觀」以下，並官喚反，餘不出者，並音官。</p><p>九五：觀我生，君子無咎。居於尊位，為觀之主，宣弘大化，光於四表，觀之極者也。上之化下，猶風之靡草，故觀民之俗，以察己道。百姓有罪，在予一人。君子風著，己乃無咎。上為化主，將欲自觀，乃觀民也。象曰：「觀我生」，觀民也。正義曰：九五居尊，為觀之主。四海之內，由我而化。我教化善，則天下有君子之風；教化不善，則天下著小人之俗。故觀民以察我道，有君子之風著，則無咎也。周易要義卷二下</p>',32)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
